package com.greenocean.backend.wellbeing.service;

import com.greenocean.backend.common.exception.*;
import com.greenocean.backend.identity.AccessPolicy;
import com.greenocean.backend.auth.service.AuthRateLimit;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;

/** Owner-scoped private lifecycle, separate from social publication and moderation. */
@Service
@Transactional
public class PrivateWellbeing {
 private final JdbcTemplate db; private final AccessPolicy access; private final AuthRateLimit rates; private final boolean sensitive;
 public PrivateWellbeing(JdbcTemplate db,AccessPolicy access,AuthRateLimit rates,@Value("${greenocean.wellbeing.new-sensitive-processing:false}")boolean sensitive){this.db=db;this.access=access;this.rates=rates;this.sensitive=sensitive;}
 public void actor(UUID user){if(db.queryForList("SELECT id FROM users WHERE id=? AND status='ACTIVE' FOR SHARE",UUID.class,user).isEmpty())throw new ForbiddenException("The account is unavailable");access.require(user,"COMMUNITY");if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM account_eligibility WHERE user_id=? AND age_result='ADULT')",Boolean.class,user)))throw new ForbiddenException("Verified adult eligibility is required for this experience.");if(!rates.allowInCurrentTransaction("private-wellbeing:"+user,600,Duration.ofHours(1)))throw new com.greenocean.backend.listener.live.LiveSupportException(429,"RATE_LIMITED","Please pause and try again.");}
 private void processing(){if(!sensitive)throw new com.greenocean.backend.listener.live.LiveSupportException(503,"PRIVATE_PROCESSING_DISABLED","New private storage is awaiting its processing approval.");}
 public static String text(String value,int max,boolean required){String s=value==null?"":value.trim();if(s.length()>max||(required&&s.isBlank())||s.indexOf('\u0000')>=0)throw new IllegalArgumentException("Private input length is invalid");return s;}
 public record Writing(String title,String body,String mood,List<String> tags,long revision,UUID clientKey){}
 public record Mood(String mood,String note,long revision,UUID clientKey){}
 public record Goal(String title,String cadence,String lifecycle,long revision){}
 public record Step(String title,boolean completed,long revision){}
 public record Answer(UUID setId,int position,String body,long revision){}
 private String table(String kind){return switch(kind){case "journal"->"wellbeing_journal_entries";case "check-ins"->"wellbeing_check_ins";case "goals"->"wellbeing_goals";default->throw new IllegalArgumentException("Unknown private category");};}
 public Map<String,Object> one(UUID user,String kind,UUID id){actor(user);var rows=db.queryForList("SELECT * FROM "+table(kind)+" WHERE user_id=? AND id=?",user,id);if(rows.isEmpty())throw new NotFoundException("Private record was not found");var row=new LinkedHashMap<>(rows.getFirst());row.remove("user_id");row.remove("client_key");if(kind.equals("journal")){row.put("tags",db.queryForObject("SELECT tags FROM wellbeing_journal_entries WHERE id=?",(r,n)->Arrays.asList((String[])r.getArray(1).getArray()),id));}if(kind.equals("goals")){row.put("steps",db.queryForList("SELECT id,title,completed,position FROM wellbeing_goal_steps WHERE goal_id=? ORDER BY position,id",id));int total=((List<?>)row.get("steps")).size();long done=((List<Map<String,Object>>)row.get("steps")).stream().filter(x->Boolean.TRUE.equals(x.get("completed"))).count();row.put("derivedProgress",total==0?null:(int)(done*100/total));}return row;}
 public Map<String,Object> history(UUID user,String kind,int size,int page,String search,boolean oldest){actor(user);if(size<1||size>50||page<0||page>100000)throw new IllegalArgumentException("Invalid private page");String t=table(kind);String q=text(search,160,false);String filter=kind.equals("journal")?" AND (position(lower(?) in lower(title))>0 OR position(lower(?) in lower(body))>0)":"";var args=new ArrayList<Object>();args.add(user);if(kind.equals("journal")){args.add(q);args.add(q);}args.add(size+1);args.add((long)page*size);var ids=db.queryForList("SELECT id FROM "+t+" WHERE user_id=?"+filter+" ORDER BY created_at "+(oldest?"ASC":"DESC")+",id "+(oldest?"ASC":"DESC")+" LIMIT ? OFFSET ?",UUID.class,args.toArray());boolean more=ids.size()>size;return Map.of("items",ids.stream().limit(size).map(id->one(user,kind,id)).toList(),"hasMore",more,"page",page);}
 public Map<String,Object> write(UUID user,UUID id,Writing in){actor(user);String title=text(in.title(),160,false),body=text(in.body(),20000,true),mood=text(in.mood(),40,false);List<String> tags=in.tags()==null?List.of():in.tags();if(tags.size()>12)throw new IllegalArgumentException("At most twelve private tags");String[] clean=tags.stream().map(x->text(x,40,true)).distinct().toArray(String[]::new);if(id==null){if(in.clientKey()==null)throw new IllegalArgumentException("A retry key is required");var prior=db.queryForList("SELECT id FROM wellbeing_journal_entries WHERE user_id=? AND client_key=?",UUID.class,user,in.clientKey());if(!prior.isEmpty())return one(user,"journal",prior.getFirst());id=db.queryForObject("INSERT INTO wellbeing_journal_entries(user_id,title,body,mood,tags,client_key) VALUES (?,?,?,?,?,?) ON CONFLICT(user_id,client_key) WHERE client_key IS NOT NULL DO UPDATE SET client_key=EXCLUDED.client_key RETURNING id",UUID.class,user,title.isBlank()?"Untitled reflection":title,body,mood,clean,in.clientKey());}else{one(user,"journal",id);if(db.update("UPDATE wellbeing_journal_entries SET title=?,body=?,mood=?,tags=?,revision=revision+1 WHERE id=? AND user_id=? AND revision=?",title.isBlank()?"Untitled reflection":title,body,mood,clean,id,user,in.revision())!=1)throw new ConflictException("The entry changed. Reload before saving; your unsaved writing was not overwritten.");}return one(user,"journal",id);}
 public Map<String,Object> mood(UUID user,UUID id,Mood in){actor(user);String label=text(in.mood(),40,true),note=text(in.note(),1000,false);if(id==null){if(in.clientKey()==null)throw new IllegalArgumentException("A retry key is required");id=db.queryForObject("INSERT INTO wellbeing_check_ins(user_id,mood,note,client_key) VALUES (?,?,?,?) ON CONFLICT(user_id,client_key) WHERE client_key IS NOT NULL DO UPDATE SET client_key=EXCLUDED.client_key RETURNING id",UUID.class,user,label,note,in.clientKey());}else{one(user,"check-ins",id);if(db.update("UPDATE wellbeing_check_ins SET mood=?,note=?,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=? AND revision=?",label,note,id,user,in.revision())!=1)throw new ConflictException("This mood record changed. Reload before editing.");}return one(user,"check-ins",id);}
 public void delete(UUID user,String kind,UUID id){actor(user);if(db.update("DELETE FROM "+table(kind)+" WHERE user_id=? AND id=?",user,id)!=1)throw new NotFoundException("Private record was not found");}
 public Map<String,Object> summary(UUID user,String timezone,String from,String until){actor(user);ZoneId zone=ZoneId.of(timezone);LocalDate a=LocalDate.parse(from),b=LocalDate.parse(until);if(b.isBefore(a)||Duration.between(a.atStartOfDay(),b.atStartOfDay()).toDays()>366)throw new IllegalArgumentException("Choose up to 366 days");var rows=db.queryForList("SELECT (created_at AT TIME ZONE ?)::date AS local_date,mood,count(*) AS observations FROM wellbeing_check_ins WHERE user_id=? AND created_at>=? AND created_at<? GROUP BY 1,mood ORDER BY 1,mood",zone.getId(),user,a.atStartOfDay(zone).toOffsetDateTime(),b.plusDays(1).atStartOfDay(zone).toOffsetDateTime());return Map.of("items",rows,"timezone",zone.getId(),"scope","Self-recorded observations only; missing days have no inferred value.");}
 private void goalLock(UUID user,UUID goal,long revision){one(user,"goals",goal);var rows=db.queryForList("SELECT revision FROM wellbeing_goals WHERE id=? AND user_id=? FOR UPDATE",goal,user);if(rows.isEmpty())throw new NotFoundException("Goal was not found");if(((Number)rows.getFirst().get("revision")).longValue()!=revision)throw new ConflictException("Goal changed. Reload before editing.");}
 public Map<String,Object> goal(UUID user,UUID id,Goal in){actor(user);String title=text(in.title(),160,true),cadence=text(in.cadence(),40,false),state=in.lifecycle()==null?"ACTIVE":in.lifecycle();if(!Set.of("ACTIVE","PAUSED","COMPLETED","ARCHIVED").contains(state))throw new IllegalArgumentException("Unknown goal status");if(id==null)id=db.queryForObject("INSERT INTO wellbeing_goals(user_id,title,cadence,lifecycle) VALUES (?,?,?,?) RETURNING id",UUID.class,user,title,cadence,state);else{goalLock(user,id,in.revision());if(state.equals("COMPLETED")&&Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM wellbeing_goal_steps WHERE goal_id=? AND NOT completed)",Boolean.class,id)))throw new ConflictException("Finish or edit the remaining goal steps first.");db.update("UPDATE wellbeing_goals SET title=?,cadence=?,lifecycle=?,completed=?,revision=revision+1 WHERE id=?",title,cadence,state,state.equals("COMPLETED"),id);}return one(user,"goals",id);}
 public Map<String,Object> step(UUID user,UUID goal,UUID step,Step in,boolean remove){actor(user);goalLock(user,goal,in.revision());if(step==null){int count=db.queryForObject("SELECT count(*) FROM wellbeing_goal_steps WHERE goal_id=?",Integer.class,goal);if(count>=50)throw new IllegalArgumentException("At most fifty goal steps");db.update("INSERT INTO wellbeing_goal_steps(goal_id,title,completed,position) VALUES (?,?,?,?)",goal,text(in.title(),300,true),in.completed(),count);}else if(remove){if(db.update("DELETE FROM wellbeing_goal_steps WHERE id=? AND goal_id=?",step,goal)!=1)throw new NotFoundException("Step was not found");}else if(db.update("UPDATE wellbeing_goal_steps SET title=?,completed=? WHERE id=? AND goal_id=?",text(in.title(),300,true),in.completed(),step,goal)!=1)throw new NotFoundException("Step was not found");db.update("UPDATE wellbeing_goals SET revision=revision+1,completed=FALSE,lifecycle=CASE WHEN lifecycle='COMPLETED' THEN 'ACTIVE' ELSE lifecycle END WHERE id=?",goal);return one(user,"goals",goal);}
 public Map<String,Object> daily(UUID user,String timezone,String language){actor(user);processing();ZoneId zone=ZoneId.of(timezone);if(!Set.of("en","fa").contains(language))throw new IllegalArgumentException("Unsupported language");db.queryForList("SELECT id FROM users WHERE id=? FOR NO KEY UPDATE",user);LocalDate day=db.queryForObject("SELECT CURRENT_TIMESTAMP",OffsetDateTime.class).atZoneSameInstant(zone).toLocalDate();var sets=db.queryForList("SELECT id FROM wellbeing_daily_sets WHERE user_id=? AND local_date=?",UUID.class,user,day);UUID id;if(sets.isEmpty()){var prompts=db.queryForList("SELECT id FROM wellbeing_prompt_versions WHERE wellbeing_prompt_available(id) AND language=? ORDER BY md5(id::text || ?),id LIMIT 3",UUID.class,language,day.toString());if(prompts.size()!=3)return Map.of("available",false,"date",day,"timezone",zone.getId(),"items",List.of());id=db.queryForObject("INSERT INTO wellbeing_daily_sets(user_id,local_date,timezone,language) VALUES (?,?,?,?) RETURNING id",UUID.class,user,day,zone.getId(),language);for(int n=0;n<3;n++)db.update("INSERT INTO wellbeing_daily_questions(set_id,position,prompt_id) VALUES (?,?,?)",id,n+1,prompts.get(n));}else id=sets.getFirst();return Map.of("available",true,"set",db.queryForMap("SELECT id,local_date,timezone,language FROM wellbeing_daily_sets WHERE id=?",id),"items",questions(user,id));}
 private List<Map<String,Object>> questions(UUID user,UUID id){return db.queryForList("SELECT q.position,p.id AS prompt_id,p.revision AS prompt_revision,p.body AS question,a.id AS answer_id,a.body AS answer,a.revision FROM wellbeing_daily_sets s JOIN wellbeing_daily_questions q ON q.set_id=s.id JOIN wellbeing_prompt_versions p ON p.id=q.prompt_id LEFT JOIN wellbeing_daily_answers a ON a.set_id=q.set_id AND a.position=q.position WHERE s.user_id=? AND s.id=? ORDER BY q.position",user,id);}
 public List<Map<String,Object>> dailyHistory(UUID user,int page){actor(user);if(page<0||page>100000)throw new IllegalArgumentException("Invalid history page");var rows=db.queryForList("SELECT id,local_date,timezone,language FROM wellbeing_daily_sets WHERE user_id=? ORDER BY local_date DESC,id DESC LIMIT 20 OFFSET ?",user,(long)page*20);for(var row:rows)row.put("items",questions(user,(UUID)row.get("id")));return rows;}
 public Map<String,Object> answer(UUID user,Answer in,boolean remove){actor(user);if(!remove)processing();if(questions(user,in.setId()).stream().noneMatch(x->Objects.equals(x.get("position"),Short.valueOf((short)in.position()))||((Number)x.get("position")).intValue()==in.position()))throw new NotFoundException("Daily question was not found");db.queryForList("SELECT id FROM wellbeing_daily_sets WHERE id=? FOR UPDATE",in.setId());var rows=db.queryForList("SELECT id,revision FROM wellbeing_daily_answers WHERE set_id=? AND position=?",in.setId(),in.position());if(!rows.isEmpty()&&((Number)rows.getFirst().get("revision")).longValue()!=in.revision())throw new ConflictException("Daily answer changed. Reload before editing.");if(remove){db.update("DELETE FROM wellbeing_daily_answers WHERE set_id=? AND position=?",in.setId(),in.position());return Map.of();}String body=text(in.body(),20000,true);if(rows.isEmpty()){if(in.revision()!=-1)throw new ConflictException("The answer was removed. Reload before saving.");db.update("INSERT INTO wellbeing_daily_answers(set_id,position,body) VALUES (?,?,?)",in.setId(),in.position(),body);}else db.update("UPDATE wellbeing_daily_answers SET body=?,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE set_id=? AND position=?",body,in.setId(),in.position());return Map.of("items",questions(user,in.setId()));}
 public Map<String,Object> draft(UUID user,Writing in,boolean remove){actor(user);if(remove){db.update("DELETE FROM wellbeing_journal_drafts WHERE user_id=?",user);return Map.of();}if(in!=null){processing();db.queryForList("SELECT id FROM users WHERE id=? FOR NO KEY UPDATE",user);db.update("DELETE FROM wellbeing_journal_drafts WHERE user_id=? AND expires_at<=CURRENT_TIMESTAMP",user);var rows=db.queryForList("SELECT revision FROM wellbeing_journal_drafts WHERE user_id=?",user);if(rows.isEmpty()){if(in.revision()!=-1)throw new ConflictException("Draft expired or was removed. Reload first.");db.update("INSERT INTO wellbeing_journal_drafts(user_id,title,body,mood) VALUES (?,?,?,?)",user,text(in.title(),160,false),text(in.body(),20000,false),text(in.mood(),40,false));}else if(db.update("UPDATE wellbeing_journal_drafts SET title=?,body=?,mood=?,revision=revision+1,updated_at=CURRENT_TIMESTAMP,expires_at=CURRENT_TIMESTAMP+INTERVAL '7 days' WHERE user_id=? AND revision=?",text(in.title(),160,false),text(in.body(),20000,false),text(in.mood(),40,false),user,in.revision())!=1)throw new ConflictException("Draft changed on another device.");}var rows=db.queryForList("SELECT title,body,mood,revision,updated_at,expires_at FROM wellbeing_journal_drafts WHERE user_id=? AND expires_at>CURRENT_TIMESTAMP",user);return Map.of("items",rows,"durableEnabled",sensitive);}
 @org.springframework.scheduling.annotation.Scheduled(fixedDelayString="${greenocean.wellbeing.draft-cleanup-ms:60000}")
 public void expireDrafts(){if(sensitive)db.update("DELETE FROM wellbeing_journal_drafts WHERE user_id IN(SELECT user_id FROM wellbeing_journal_drafts WHERE expires_at<=CURRENT_TIMESTAMP ORDER BY expires_at LIMIT 100)");}
}
